import{_ as e,o,c as l,a4 as a}from"./chunks/framework.C7iBV1LP.js";const p=JSON.parse('{"title":"The Fleet 🪐","description":"","frontmatter":{},"headers":[],"relativePath":"fleet/index.md","filePath":"fleet/index.md"}'),r={name:"fleet/index.md"};function s(n,t,i,d,c,g){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="the-fleet-🪐" tabindex="-1">The Fleet 🪐 <a class="header-anchor" href="#the-fleet-🪐" aria-label="Permalink to &quot;The Fleet 🪐&quot;">​</a></h1><p>Solar orchestrates an entire constellation of 15 specialized machines across desktop workstations, portable laptops, handheld gaming devices, central storage servers, and a High-Availability Kubernetes cluster.</p><hr><h2 id="🗺️-the-constellation-map" tabindex="-1">🗺️ The Constellation Map <a class="header-anchor" href="#🗺️-the-constellation-map" aria-label="Permalink to &quot;🗺️ The Constellation Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Celestial Namesake</th><th style="text-align:left;">Role &amp; Architecture</th><th style="text-align:left;">Platform &amp; UI</th><th style="text-align:left;">Storage Configuration</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>sol</code></strong></td><td style="text-align:left;">The Sun (Central Star)</td><td style="text-align:left;"><strong>Central Fleet ZFS NAS</strong><br>• Storage Server (NVMe + HDDs)</td><td style="text-align:left;">Headless Server</td><td style="text-align:left;">Ephemeral <code>tmpfs</code> + 1x NVMe + 2x HDD (ZFS Mirror <code>tank</code>)</td></tr><tr><td style="text-align:left;"><strong><code>mars</code></strong></td><td style="text-align:left;">Planet Mars</td><td style="text-align:left;"><strong>Primary Workstation</strong><br>• AMD CPU + Nvidia GPU</td><td style="text-align:left;">Niri (Sky Theme)</td><td style="text-align:left;">Ephemeral <code>tmpfs</code> + 2x NVMe + 2x HDD</td></tr><tr><td style="text-align:left;"><strong><code>mercury</code></strong></td><td style="text-align:left;">Planet Mercury</td><td style="text-align:left;"><strong>Portable Laptop</strong><br>• Intel CPU/iGPU</td><td style="text-align:left;">Niri (Sky Theme)</td><td style="text-align:left;">Ephemeral <code>tmpfs</code> + 1x NVMe</td></tr><tr><td style="text-align:left;"><strong><code>phobos</code></strong></td><td style="text-align:left;">Moon of Mars</td><td style="text-align:left;"><strong>MacBook</strong><br>• Apple Silicon (<code>aarch64-darwin</code>)</td><td style="text-align:left;">macOS + nix-darwin</td><td style="text-align:left;">APFS Encrypted</td></tr><tr><td style="text-align:left;"><strong><code>pluto</code></strong></td><td style="text-align:left;">Dwarf Planet Pluto</td><td style="text-align:left;"><strong>K3s HA Bootstrap Master</strong><br>• Beelink EQR5 (Ryzen 7 5825U, 32GB RAM)</td><td style="text-align:left;">Headless / K3s HA</td><td style="text-align:left;">Ephemeral <code>tmpfs</code> + 1x NVMe (Stateless K3s)</td></tr><tr><td style="text-align:left;"><strong><code>styx</code></strong></td><td style="text-align:left;">Moon of Pluto (Styx)</td><td style="text-align:left;"><strong>K3s HA Master Node 2</strong><br>• ThinkCentre M920q (i5-9500T, 16GB RAM)</td><td style="text-align:left;">Headless / K3s HA</td><td style="text-align:left;">Ephemeral <code>tmpfs</code> + 1x NVMe (Stateless K3s)</td></tr><tr><td style="text-align:left;"><strong><code>hydra</code></strong></td><td style="text-align:left;">Moon of Pluto (Hydra)</td><td style="text-align:left;"><strong>K3s HA Master Node 3</strong><br>• ThinkCentre M920q (i5-8500T, 24GB RAM)</td><td style="text-align:left;">Headless / K3s HA</td><td style="text-align:left;">Ephemeral <code>tmpfs</code> + 1x NVMe (Stateless K3s)</td></tr><tr><td style="text-align:left;"><strong><code>thebe</code></strong></td><td style="text-align:left;">Inner Moon (Jupiter XIV)</td><td style="text-align:left;"><strong>Compact Standalone Server</strong><br>• Intel Mac Mini (Core CPU &amp; iGPU)</td><td style="text-align:left;">Headless / Limine</td><td style="text-align:left;">Standard Btrfs + LUKS2</td></tr><tr><td style="text-align:left;"><strong><code>venus</code></strong></td><td style="text-align:left;">Planet Venus</td><td style="text-align:left;"><strong>Multi-Service Server</strong><br>• AMD CPU</td><td style="text-align:left;">Headless Server</td><td style="text-align:left;">Standard Btrfs + 1x NVMe</td></tr><tr><td style="text-align:left;"><strong><code>elara</code></strong></td><td style="text-align:left;">Moon of Jupiter</td><td style="text-align:left;"><strong>Gaming Rig</strong><br>• AMD CPU + Nvidia GPU</td><td style="text-align:left;">KDE Plasma 6 (Strawberry)</td><td style="text-align:left;">Standard Btrfs + 1x SSD</td></tr><tr><td style="text-align:left;"><strong><code>europa</code></strong></td><td style="text-align:left;">Moon of Jupiter</td><td style="text-align:left;"><strong>VR Workstation</strong><br>• Intel CPU + Nvidia GPU</td><td style="text-align:left;">KDE Plasma 6 (Forest)</td><td style="text-align:left;">Standard Btrfs + 1x SSD</td></tr><tr><td style="text-align:left;"><strong><code>amalthea</code></strong></td><td style="text-align:left;">Moon of Jupiter</td><td style="text-align:left;"><strong>Handheld Console</strong><br>• Intel Atom z8350</td><td style="text-align:left;">Steam Big Picture (Gamescope)</td><td style="text-align:left;">Standard Btrfs + eMMC/SD</td></tr><tr><td style="text-align:left;"><strong><code>io</code></strong></td><td style="text-align:left;">Moon of Jupiter</td><td style="text-align:left;"><strong>Testbed Node</strong><br>• x86_64 Linux</td><td style="text-align:left;">COSMIC Desktop (Space)</td><td style="text-align:left;">Standard Btrfs</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Deprecated Legacy Hosts</p><p>Legacy storage hosts <strong><code>ganymede</code></strong> (Dedicated NAS) and <strong><code>callisto</code></strong> (Storage &amp; Backup) have been retired in favor of <strong><code>sol</code></strong> (Central ZFS NAS) and the <strong>Pluto Cluster</strong>. <strong><code>thebe</code></strong> remains actively maintained as a standalone compact server.</p></div><hr><h2 id="🌑-the-pluto-k3s-ha-cluster" tabindex="-1">🌑 The Pluto K3s HA Cluster <a class="header-anchor" href="#🌑-the-pluto-k3s-ha-cluster" aria-label="Permalink to &quot;🌑 The Pluto K3s HA Cluster&quot;">​</a></h2><p>The <strong>Pluto Cluster</strong> is a 3-node High-Availability Kubernetes control plane powered by an embedded etcd quorum.</p><ul><li><strong>Nodes</strong>: <strong><code>pluto</code></strong> (Bootstrap Master), <strong><code>styx</code></strong> (Master 2), and <strong><code>hydra</code></strong> (Master 3).</li><li><strong>Multi-Tier Storage</strong>: Longhorn replicated block storage on M920qs, Pluto NVMe NFS, and local NVMe paths.</li><li><strong>Staggered Reboots</strong>: System updates and automatic reboots occur Sundays 30 minutes apart to preserve etcd quorum: <ul><li><code>pluto</code>: Sun 03:00</li><li><code>styx</code>: Sun 03:30</li><li><code>hydra</code>: Sun 04:00</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">📖 Pluto Cluster Guides &amp; Runbooks</p><ul><li><strong><a href="/solar-docs/fleet/pluto-cluster">Cluster Architecture</a></strong>: Hardware specifications, node roles, network ingress, and topology.</li><li><strong><a href="/solar-docs/fleet/pluto-cluster/migration">Workload Migration Runbook</a></strong>: Detailed transition runbook for Joplin, Zotero, Factorio, and Minecraft.</li><li><strong><a href="/solar-docs/fleet/pluto-cluster/transfer">Venus ➔ Pluto Transfer Guide</a></strong>: Step-by-step physical hardware migration and Hydra staging manual.</li><li><strong><a href="/solar-docs/fleet/pluto-cluster/secrets">Secrets &amp; Security Guide</a></strong>: Zero-plaintext Age secrets, YubiKey encryption, and Kubernetes secret injection.</li><li><strong><a href="/solar-docs/fleet/pluto-cluster/setup">Setup &amp; Operations Guide</a></strong>: Full cluster deployment, bootstrapping, and day-2 administration manual.</li></ul></div><hr><h2 id="☀️-sol-central-fleet-zfs-nas" tabindex="-1">☀️ Sol (Central Fleet ZFS NAS) <a class="header-anchor" href="#☀️-sol-central-fleet-zfs-nas" aria-label="Permalink to &quot;☀️ Sol (Central Fleet ZFS NAS)&quot;">​</a></h2><ul><li><strong>Storage Layout</strong>: Mirrored 3.5&quot; HDD storage pool (<strong><code>tank</code></strong>) with LZ4 compression, POSIX ACLs, and automated snapshots.</li><li><strong>NFS Export</strong>: Exports <code>/tank/k3s-volumes</code> to cluster subnet for dynamic persistent volumes.</li><li><strong>Samba SMB3</strong>: Encrypted network file shares (<code>/tank/storage</code>, <code>/tank/media</code>) with Avahi mDNS discovery (<code>sol.local</code>).</li><li><strong>Maintenance</strong>: Automated weekly ZFS scrubs and SMART diagnostics.</li></ul><hr><h2 id="☁️-venus-multi-service-cloud" tabindex="-1">☁️ Venus (Multi-Service Cloud) <a class="header-anchor" href="#☁️-venus-multi-service-cloud" aria-label="Permalink to &quot;☁️ Venus (Multi-Service Cloud)&quot;">​</a></h2><ul><li><strong>Web Proxy</strong>: Automated Nginx reverse proxy with dynamic DNS and Lego Let&#39;s Encrypt SSL.</li><li><strong>Productivity</strong>: Joplin note synchronization, Zotero research backend, and LanguageTool grammar server.</li><li><strong>Game Hosting</strong>: Dedicated Factorio server and NeoForge Minecraft servers.</li></ul><hr><h2 id="🛰️-thebe-intel-mac-mini-server" tabindex="-1">🛰️ Thebe (Intel Mac Mini Server) <a class="header-anchor" href="#🛰️-thebe-intel-mac-mini-server" aria-label="Permalink to &quot;🛰️ Thebe (Intel Mac Mini Server)&quot;">​</a></h2><ul><li><strong>Hardware</strong>: Repurposed Intel Mac Mini running headless NixOS with <code>applesmc</code> thermal control.</li><li><strong>Security</strong>: Disko LUKS2 encryption, AppArmor profiles, and Tailscale mesh networking.</li><li><strong>Zero-Secret Bootstrap</strong>: Operates completely self-contained with no private secret dependencies.</li></ul><hr><h2 id="🚀-workstations-mobility" tabindex="-1">🚀 Workstations &amp; Mobility <a class="header-anchor" href="#🚀-workstations-mobility" aria-label="Permalink to &quot;🚀 Workstations &amp; Mobility&quot;">​</a></h2><h3 id="mars-primary-desktop" tabindex="-1">Mars (Primary Desktop) <a class="header-anchor" href="#mars-primary-desktop" aria-label="Permalink to &quot;Mars (Primary Desktop)&quot;">​</a></h3><ul><li>AMD CPU + Nvidia GPU powering the scrollable Niri Wayland compositor.</li><li>Wipe-on-boot tmpfs root, multi-NVMe speed pool + HDD storage pool.</li><li>Sunshine game streaming host and Wooting analog keyboard support.</li></ul><h3 id="mercury-portable-laptop" tabindex="-1">Mercury (Portable Laptop) <a class="header-anchor" href="#mercury-portable-laptop" aria-label="Permalink to &quot;Mercury (Portable Laptop)&quot;">​</a></h3><ul><li>Intel CPU with aggressive power saving profiles via TLP.</li><li>Niri Wayland compositor with gesture-driven workspace navigation.</li><li>Ephemeral root on fast NVMe.</li></ul><h3 id="phobos-apple-silicon-macbook" tabindex="-1">Phobos (Apple Silicon MacBook) <a class="header-anchor" href="#phobos-apple-silicon-macbook" aria-label="Permalink to &quot;Phobos (Apple Silicon MacBook)&quot;">​</a></h3><ul><li>Managed via <code>nix-darwin</code> with declarative system preferences.</li><li>Raycast, Homebrew bundles, and unified shell tools with Linux hosts.</li></ul>',28)])])}const h=e(r,[["render",s]]);export{p as __pageData,h as default};
